#include <stdio.h>
#include "recovery_io.h"
#include <string.h>
#include <stdlib.h>
#include "dashboard.h"
void ah_dashboard_defaults(struct AHDashboardLayout *l){memset(l,0,sizeof(*l));strcpy(l->name,"My dashboard");l->columns=2;l->rows=3;}
unsigned int ah_dashboard_count(const struct AHDashboardLayout *l){return l->columns*l->rows;}
unsigned int ah_dashboard_actions(const char *entity,const char **labels,unsigned int cap)
{if(!strncmp(entity,"button.",7)||!strncmp(entity,"input_button.",13)){if(cap)labels[0]="Read only";if(cap>1)labels[1]="Press";return 2;}if(!strncmp(entity,"camera.",7)){if(cap)labels[0]="Read only";if(cap>1)labels[1]="Snapshot";return 2;}if(!strncmp(entity,"media_player.",13)){static const char *media[]={"Read only","Controls","Play","Pause","Previous","Next"};unsigned int i;for(i=0;i<6&&i<cap;++i)labels[i]=media[i];return 6;}static const char *actions[]={"Read only","Toggle","Turn on","Turn off","Activate","Controls","Lock","Unlock","Open lock","Open cover","Close cover","Stop cover",
  "Run","Confirm and run","Trigger","Next option","Previous option","Start","Pause cleaning","Stop","Return home","Open valve","Close valve","Stop valve","Arm home","Arm away","Arm night","Disarm","HVAC off","HVAC heat","HVAC cool","HVAC auto","HVAC heat_cool"};
 unsigned int i,n=0;char path[96],body[180];int scene=!strncmp(entity,"scene.",6)||!strncmp(entity,"script.",7);
 for(i=0;i<sizeof(actions)/sizeof(actions[0]);++i){if((i==5 && (!strncmp(entity,"light.",6)||!strncmp(entity,"climate.",8))) || !i || (amihass_action(entity,actions[i],path,body) && (!scene || i==4 || i==13))){if(n<cap)labels[n]=actions[i];++n;}}return n;}
unsigned int ah_dashboard_supported_actions(const char *entity,const struct AHControls *c,int known,const char **labels,unsigned int cap)
{const char *all[AH_DASH_ACTIONS];unsigned int i,n,used=0;if(!strncmp(entity,"camera.",7))return ah_dashboard_actions(entity,labels,cap);n=ah_dashboard_actions(entity,all,AH_DASH_ACTIONS);for(i=0;i<n&&i<AH_DASH_ACTIONS;++i){if(i&&(!known||!amihass_control_allowed(c,all[i])||(!strcmp(all[i],"Controls")&&!c->brightness&&!c->color&&!c->temperature&&!c->media_play&&!c->media_pause&&!c->media_previous&&!c->media_next&&!c->media_volume)))continue;if(used<cap)labels[used]=all[i];++used;}return used;}
unsigned int ah_dashboard_editor_actions(const char *entity,const struct AHControls *c,int known,const char *saved,const char **labels,unsigned int cap)
{unsigned int i,n=ah_dashboard_supported_actions(entity,c,known,labels,cap);if(saved&&*saved){for(i=0;i<n&&i<cap;++i)if(!strcmp(labels[i],saved))return n;if(n<cap)labels[n++]=saved;}return n;}
int ah_dashboard_confirm_required(const char *entity,const char *action,int sample)
{return !sample&&(amihass_action_sensitive(entity,action)||(action&&!strcmp(action,"Confirm and run")));}
static int action_valid(const struct AHDashboardTile *t)
{const char *labels[AH_DASH_ACTIONS];unsigned int i,n;if(!t->action[0])return 1;n=ah_dashboard_actions(t->entity,labels,AH_DASH_ACTIONS);for(i=1;i<n;++i)if(!strcmp(t->action,labels[i]))return 1;return 0;}
void ah_dashboard_sample(struct AHDashboardLayout *l)
{static const char *ids[]={"light.amihass_sample_living_room","light.amihass_sample_desk","switch.amihass_sample_coffee_machine","sensor.amihass_sample_living_room_temperature","sensor.amihass_sample_outdoor_humidity","fan.amihass_sample_bedroom"};static const char *names[]={"Living room","Desk lamp","Coffee machine","Temperature","Humidity","Bedroom fan"};int i;ah_dashboard_defaults(l);strcpy(l->name,"Sample home");for(i=0;i<6;++i){strcpy(l->tiles[i].label,names[i]);strcpy(l->tiles[i].entity,ids[i]);if(i<3||i==5)strcpy(l->tiles[i].action,"Toggle");}}
int ah_dashboard_move(struct AHDashboardLayout *l,unsigned int from,unsigned int to)
{struct AHDashboardTile t;if(from>=ah_dashboard_count(l)||to>=ah_dashboard_count(l)||from>=AH_DASH_TILES||to>=AH_DASH_TILES)return 0;t=l->tiles[from];l->tiles[from]=l->tiles[to];l->tiles[to]=t;return 1;}
int ah_dashboard_resize(struct AHDashboardLayout *l,unsigned int cols,unsigned int rows)
{struct AHDashboardLayout draft;unsigned int r,c,index;if(cols<1||cols>4||rows<1||rows>6||cols*rows>AH_DASH_TILES)return 0;ah_dashboard_defaults(&draft);strcpy(draft.name,l->name);draft.columns=cols;draft.rows=rows;for(r=0;r<l->rows;++r)for(c=0;c<l->columns;++c){index=r*l->columns+c;if(index>=AH_DASH_TILES)return 0;if(r>=rows||c>=cols){if(l->tiles[index].entity[0]||l->tiles[index].label[0])return 0;}else draft.tiles[r*cols+c]=l->tiles[index];}*l=draft;return 1;}
static int line(FILE *f,char *out,unsigned int cap)
{unsigned int n=0;int c;while((c=fgetc(f))!=EOF){if(c=='\n'){out[n]=0;return 1;}if(c=='\r')continue;if(c<32||c==127||n+1>=cap)return 0;out[n++]=(char)c;}return 0;}
static int label_valid(const char *s){const unsigned char *p=(const unsigned char *)s;if(strlen(s)>32)return 0;for(;*p;++p)if(*p<32||*p==127)return 0;return 1;}
static int valid(const struct AHDashboardLayout *l)
{unsigned int i;if(!*l->name||!label_valid(l->name)||l->columns<1||l->columns>4||l->rows<1||l->rows>6||ah_dashboard_count(l)>AH_DASH_TILES)return 0;for(i=0;i<AH_DASH_TILES;++i)if(!label_valid(l->tiles[i].label)||(*l->tiles[i].entity&&!amihass_entity_id(l->tiles[i].entity))||!action_valid(&l->tiles[i])||!ah_dashboard_refresh_valid(l->tiles[i].refresh)||l->tiles[i].display>7||l->tiles[i].gauge_min < -100000000L||l->tiles[i].gauge_min>100000000L||l->tiles[i].gauge_max < -100000000L||l->tiles[i].gauge_max>100000000L||(l->tiles[i].display==4&&(l->tiles[i].gauge_min>=l->tiles[i].gauge_max||l->tiles[i].gauge_min < -100000000L||l->tiles[i].gauge_max>100000000L))||l->tiles[i].timestamp>1||(i>=ah_dashboard_count(l)&&(l->tiles[i].entity[0]||l->tiles[i].label[0])))return 0;return 1;}
int ah_dashboard_load_status(struct AHDashboardLayout *l,const char *path,int *recovered)
{struct AHDashboardLayout draft;FILE *f;char recovery[520],header[32],size[32],extra;unsigned int i,count;int ok,v2;if(recovered)*recovered=0;ah_dashboard_defaults(l);f=fopen(path,"rb");if(!f){if(!ah_file_missing(path))return 0;if(strlen(path)>=500)return 1;sprintf(recovery,"%s.old",path);f=fopen(recovery,"rb");if(!f)return ah_file_missing(recovery);if(recovered)*recovered=1;}ah_dashboard_defaults(&draft);header[0]=0;ok=line(f,header,sizeof(header));v2=!strcmp(header,"AMIHASSDASH2");ok=ok&&(v2||!strcmp(header,"AMIHASSDASH1"))&&line(f,draft.name,sizeof(draft.name));if(ok&&v2)ok=line(f,size,sizeof(size))&&sscanf(size,"%u %u %c",&draft.columns,&draft.rows,&extra)==2&&draft.columns>=1&&draft.columns<=4&&draft.rows>=1&&draft.rows<=6;count=v2 ? ah_dashboard_count(&draft):6;if(count>AH_DASH_TILES)ok=0;for(i=0;i<count&&ok;++i){ok=line(f,draft.tiles[i].label,sizeof(draft.tiles[i].label))&&line(f,draft.tiles[i].entity,sizeof(draft.tiles[i].entity));if(ok&&v2)ok=line(f,draft.tiles[i].action,sizeof(draft.tiles[i].action));}ok=ok&&fgetc(f)==EOF&&valid(&draft);fclose(f);if(ok)*l=draft;return ok;}
int ah_dashboard_save(const struct AHDashboardLayout *l,const char *path)
{FILE *f;char fresh[520],backup[520];unsigned int i;int ok=1,old=0;if(!valid(l)||strlen(path)>500)return 0;for(i=0;i<AH_DASH_TILES;++i)if(l->tiles[i].refresh||l->tiles[i].display||l->tiles[i].timestamp)return 0;sprintf(fresh,"%s.new",path);sprintf(backup,"%s.old",path);f=fopen(fresh,"wb");if(!f)return 0;if(fprintf(f,"AMIHASSDASH2\n%s\n%u %u\n",l->name,l->columns,l->rows)<0)ok=0;for(i=0;i<ah_dashboard_count(l);++i)if(fprintf(f,"%s\n%s\n%s\n",l->tiles[i].label,l->tiles[i].entity,l->tiles[i].action)<0)ok=0;if(fclose(f))ok=0;if(!ok){remove(fresh);return 0;}f=fopen(path,"rb");if(f){fclose(f);remove(backup);if(rename(path,backup)){remove(fresh);return 0;}old=1;}if(rename(fresh,path)){if(old)rename(backup,path);remove(fresh);return 0;}remove(backup);return 1;}

void ah_dashboard_book_defaults(struct AHDashboardBook *b)
{memset(b,0,sizeof(*b));b->count=1;ah_dashboard_defaults(&b->pages[0]);ah_dashboard_preset(b,"Warm white",0xffc080);ah_dashboard_preset(b,"Cool white",0xc0dfff);ah_dashboard_preset(b,"Red",0xff0000);ah_dashboard_preset(b,"Green",0x00ff00);ah_dashboard_preset(b,"Blue",0x0000ff);}
int ah_dashboard_page_add(struct AHDashboardBook *b,const char *name)
{unsigned int i;if(!*name||!label_valid(name)||b->count>=AH_DASH_PAGES)return 0;for(i=0;i<b->count;++i)if(!strcmp(name,b->pages[i].name))return 0;b->current=b->count++;ah_dashboard_defaults(&b->pages[b->current]);memset(b->pages[b->current].name,0,sizeof(b->pages[b->current].name));strcpy(b->pages[b->current].name,name);return 1;}
int ah_dashboard_page_remove(struct AHDashboardBook *b,unsigned int i)
{if(b->count<2||i>=b->count)return 0;for(;i+1<b->count;++i)b->pages[i]=b->pages[i+1];--b->count;memset(&b->pages[b->count],0,sizeof(b->pages[0]));if(b->current>=b->count)b->current=b->count-1;return 1;}
int ah_dashboard_preset(struct AHDashboardBook *b,const char *name,unsigned long rgb)
{unsigned int i;if(!*name||!label_valid(name)||rgb>0xffffff)return 0;for(i=0;i<b->preset_count;++i)if(!strcmp(name,b->presets[i].name))break;if(i==AH_DASH_PRESETS)return 0;if(i==b->preset_count)++b->preset_count;strcpy(b->presets[i].name,name);b->presets[i].rgb=rgb;return 1;}
static int book_valid(const struct AHDashboardBook *b)
{unsigned int i,j;if(!b->count||b->count>AH_DASH_PAGES||b->current>=b->count||b->preset_count>AH_DASH_PRESETS||b->read_only>1)return 0;for(i=0;i<b->count;++i)if(!valid(&b->pages[i]))return 0;for(i=0;i<b->preset_count;++i){if(!*b->presets[i].name||!label_valid(b->presets[i].name)||b->presets[i].rgb>0xffffff)return 0;for(j=0;j<i;++j)if(!strcmp(b->presets[j].name,b->presets[i].name))return 0;}return 1;}
int ah_dashboard_book_load_status(struct AHDashboardBook *b,const char *path,int *recovered)
{FILE *f;char recovery[520],text[80],extra;unsigned int i,j;unsigned long rgb=0;int ok,v4,v5;struct AHDashboardBook *draft;if(recovered)*recovered=0;ah_dashboard_book_defaults(b);f=fopen(path,"rb");if(!f){if(!ah_file_missing(path))return 0;if(strlen(path)>=500)return 1;sprintf(recovery,"%s.old",path);f=fopen(recovery,"rb");if(!f)return ah_file_missing(recovery);if(recovered)*recovered=1;}if(!line(f,text,sizeof(text))){fclose(f);return 0;}v5=!strcmp(text,"AMIHASSDASH5");v4=v5||!strcmp(text,"AMIHASSDASH4");if(!v4&&strcmp(text,"AMIHASSDASH3")){fclose(f);return ah_dashboard_load_status(&b->pages[0],path,recovered);}draft=calloc(1,sizeof(*draft));if(!draft){fclose(f);return 0;}ok=line(f,text,sizeof(text))&&(v4 ? sscanf(text,"%u %u %u %u %c",&draft->count,&draft->current,&draft->preset_count,&draft->read_only,&extra)==4:sscanf(text,"%u %u %u %c",&draft->count,&draft->current,&draft->preset_count,&extra)==3)&&draft->count>0&&draft->count<=AH_DASH_PAGES&&draft->current<draft->count&&draft->preset_count<=AH_DASH_PRESETS;
for(i=0;ok&&i<draft->count;++i){struct AHDashboardLayout *l=&draft->pages[i];ok=line(f,l->name,sizeof(l->name))&&line(f,text,sizeof(text))&&sscanf(text,"%u %u %c",&l->columns,&l->rows,&extra)==2&&l->columns>=1&&l->columns<=4&&l->rows>=1&&l->rows<=6;for(j=0;ok&&j<ah_dashboard_count(l);++j){ok=line(f,l->tiles[j].label,sizeof(l->tiles[j].label))&&line(f,l->tiles[j].entity,sizeof(l->tiles[j].entity))&&line(f,l->tiles[j].action,sizeof(l->tiles[j].action));if(ok&&v4)ok=line(f,text,sizeof(text))&&(v5 ? sscanf(text,"%u %u %u %ld %ld %c",&l->tiles[j].refresh,&l->tiles[j].display,&l->tiles[j].timestamp,&l->tiles[j].gauge_min,&l->tiles[j].gauge_max,&extra)==5:sscanf(text,"%u %u %u %c",&l->tiles[j].refresh,&l->tiles[j].display,&l->tiles[j].timestamp,&extra)==3);}}
for(i=0;ok&&i<draft->preset_count;++i){ok=line(f,draft->presets[i].name,sizeof(draft->presets[i].name))&&line(f,text,sizeof(text))&&sscanf(text,"%lx %c",&rgb,&extra)==1&&rgb<=0xffffff;draft->presets[i].rgb=rgb;}ok=ok&&fgetc(f)==EOF&&book_valid(draft);fclose(f);if(ok)*b=*draft;free(draft);return ok;}
int ah_dashboard_book_save(const struct AHDashboardBook *b,const char *path)
{FILE *f;char fresh[520],backup[520];unsigned int i,j;int ok=1,old=0;if(!book_valid(b)||strlen(path)>500)return 0;sprintf(fresh,"%s.new",path);sprintf(backup,"%s.old",path);f=fopen(fresh,"wb");if(!f)return 0;if(fprintf(f,"AMIHASSDASH5\n%u %u %u %u\n",b->count,b->current,b->preset_count,b->read_only)<0)ok=0;for(i=0;i<b->count;++i){const struct AHDashboardLayout *l=&b->pages[i];if(fprintf(f,"%s\n%u %u\n",l->name,l->columns,l->rows)<0)ok=0;for(j=0;j<ah_dashboard_count(l);++j)if(fprintf(f,"%s\n%s\n%s\n%u %u %u %ld %ld\n",l->tiles[j].label,l->tiles[j].entity,l->tiles[j].action,l->tiles[j].refresh,l->tiles[j].display,l->tiles[j].timestamp,l->tiles[j].gauge_min,l->tiles[j].gauge_max)<0)ok=0;}for(i=0;i<b->preset_count;++i)if(fprintf(f,"%s\n%06lx\n",b->presets[i].name,b->presets[i].rgb)<0)ok=0;if(fclose(f))ok=0;if(!ok){remove(fresh);return 0;}f=fopen(path,"rb");if(f){fclose(f);remove(backup);if(rename(path,backup)){remove(fresh);return 0;}old=1;}if(rename(fresh,path)){if(old)rename(backup,path);remove(fresh);return 0;}remove(backup);return 1;}

int ah_dashboard_export(const struct AHDashboardBook *b,const char *path)
{size_t n;if(!path)return 0;n=strlen(path);if(n<7||strcmp(path+n-7,".ahdash"))return 0;return ah_dashboard_book_save(b,path);}
int ah_dashboard_import(struct AHDashboardBook *b,const char *path)
{struct AHDashboardBook *draft;FILE *f;int ok;if(!path||(f=fopen(path,"rb"))==NULL)return 0;fclose(f);draft=calloc(1,sizeof(*draft));if(!draft)return 0;ok=ah_dashboard_book_load(draft,path);if(ok)*b=*draft;free(draft);return ok;}
int ah_dashboard_transfer(struct AHDashboardBook *b,unsigned int fp,unsigned int from,unsigned int tp,unsigned int to,int copy)
{struct AHDashboardTile *src,*dst;if(fp>=b->count||tp>=b->count||from>=ah_dashboard_count(&b->pages[fp])||to>=ah_dashboard_count(&b->pages[tp])||(fp==tp&&from==to))return 0;src=&b->pages[fp].tiles[from];dst=&b->pages[tp].tiles[to];if(!src->entity[0]||dst->entity[0]||dst->label[0])return 0;*dst=*src;if(!copy)memset(src,0,sizeof(*src));return 1;}

int ah_dashboard_source_matches(const char *entity,int sample)
{return !entity||!*entity||((strstr(entity,".amihass_sample_")!=NULL)==(sample!=0));}

int ah_dashboard_refresh_valid(unsigned int seconds)
{return seconds==0||seconds==5||seconds==10||seconds==30||seconds==60||seconds==300||seconds==900;}
unsigned int ah_dashboard_refresh(unsigned int seconds)
{return seconds ? seconds:5;}
void ah_dashboard_value(const struct AHDashboardTile *t,const struct AmiHASSEntity *e,const struct AHControls *c,char out[96])
{char number[40];if(t->display==1||(t->display>=5&&t->display<=7)){snprintf(out,96,"%.39s %.15s",amihass_display_state(e),e->unit);return;}if(t->display==2){if(c->brightness&&c->level_known)sprintf(out,"%d%%",c->level);else strcpy(out,"Brightness unavailable");return;}if(t->display==3){if(c->temperature){amihass_number_text(c->target,number);snprintf(out,96,"%s %s",number,c->unit);}else strcpy(out,"Target unavailable");return;}snprintf(out,96,"%.39s %.15s",amihass_display_state(e),e->unit);if(c->brightness&&c->level_known)snprintf(out,96,"%.16s | %d%%",amihass_display_state(e),c->level);if(c->temperature){amihass_number_text(c->target,number);snprintf(out,96,"%.16s | %s %s",amihass_display_state(e),number,c->unit);}if(!strncmp(e->id,"media_player.",13)&&c->media_title[0])snprintf(out,96,"%.16s | %.63s",amihass_display_state(e),c->media_title);}
int ah_dashboard_template(struct AHDashboardLayout *l,unsigned int kind)
{unsigned int i;static const char *light_ids[]={"light.amihass_sample_living_room","light.amihass_sample_desk"};static const char *light_names[]={"Living room","Desk lamp"};static const char *climate_ids[]={"climate.amihass_sample_hallway","sensor.amihass_sample_living_room_temperature","sensor.amihass_sample_outdoor_humidity","weather.amihass_sample_home"};static const char *climate_names[]={"Heating","Room temperature","Humidity","Weather"};if(kind>2)return 0;if(kind==2){ah_dashboard_sample(l);memset(l->name,0,sizeof(l->name));strcpy(l->name,"Overview");return 1;}ah_dashboard_defaults(l);memset(l->name,0,sizeof(l->name));strcpy(l->name,kind==0 ? "Lighting":"Climate");l->rows=kind==0 ? 1:2;for(i=0;i<ah_dashboard_count(l);++i){struct AHDashboardTile *t=&l->tiles[i];strcpy(t->entity,kind==0 ? light_ids[i]:climate_ids[i]);strcpy(t->label,kind==0 ? light_names[i]:climate_names[i]);t->refresh=kind==0 ? 5:300;t->timestamp=1;if(kind==0){strcpy(t->action,"Controls");t->display=2;}else if(i==0){strcpy(t->action,"Controls");t->display=3;}}return 1;}

/* Background windows use four times their requested interval, bounded by the SDK. */
unsigned int ah_dashboard_poll(unsigned int seconds,int inactive)
{unsigned int n=ah_dashboard_refresh(seconds);if(inactive){if(!seconds)n=30;n=n>900 ? 3600:n*4;}return n;}
int ah_dashboard_stale(unsigned long age,unsigned int refresh)
{return refresh&&age>refresh*2UL+30UL;}
/* Direction: 0 left, 1 right, 2 up, 3 down. Occupied cells swap safely. */
int ah_dashboard_shift(struct AHDashboardLayout *l,unsigned int from,int direction)
{unsigned int to=from;if(from>=ah_dashboard_count(l))return -1;if(direction==0){if(!(from%l->columns))return -1;--to;}else if(direction==1){if(from%l->columns+1>=l->columns)return -1;++to;}else if(direction==2){if(from<l->columns)return -1;to-=l->columns;}else if(direction==3){if(from+l->columns>=ah_dashboard_count(l))return -1;to+=l->columns;}else return -1;return ah_dashboard_move(l,from,to) ? (int)to:-1;}

void ah_dashboard_estimate(const struct AHDashboardLayout *l,unsigned int first,unsigned int count,unsigned int default_poll,unsigned int *unique,unsigned long *milli_requests)
{unsigned int i,j,end,n,fastest;*unique=0;*milli_requests=0;if(default_poll<10||default_poll>3600)default_poll=30;end=ah_dashboard_count(l);if(end>AH_DASH_TILES)end=AH_DASH_TILES;if(first>=end)return;if(count<end-first)end=first+count;for(i=first;i<end;++i){if(!l->tiles[i].entity[0])continue;for(j=first;j<i;++j)if(!strcmp(l->tiles[i].entity,l->tiles[j].entity))break;if(j<i)continue;++*unique;fastest=3600;for(j=i;j<end;++j)if(!strcmp(l->tiles[i].entity,l->tiles[j].entity)){n=l->tiles[j].refresh ? l->tiles[j].refresh:default_poll;if(n<fastest)fastest=n;}*milli_requests+=60000UL/fastest;}}

int ah_dashboard_load(struct AHDashboardLayout *l,const char *path){return ah_dashboard_load_status(l,path,NULL);}
int ah_dashboard_book_load(struct AHDashboardBook *b,const char *path){return ah_dashboard_book_load_status(b,path,NULL);}

int ah_dashboard_gauge(const struct AHDashboardTile *t,const struct AmiHASSEntity *e,int result,int connected,unsigned int *percent)
{long value;unsigned long span,offset;if(t->display!=4||result!=1||!connected||!amihass_available(e)||!amihass_number(e->state,&value)||t->gauge_min>=t->gauge_max||t->gauge_min < -100000000L||t->gauge_max>100000000L)return 0;if(value<=t->gauge_min){*percent=0;return 1;}if(value>=t->gauge_max){*percent=100;return 1;}span=(unsigned long)(t->gauge_max-t->gauge_min);offset=(unsigned long)(value-t->gauge_min);{unsigned int lo=0,hi=100,mid;while(lo<hi){mid=(lo+hi+1)/2;if(offset>=(span/100)*mid+((span%100)*mid+99)/100)lo=mid;else hi=mid-1;}*percent=lo;}return 1;}

int ah_dashboard_swap(struct AHDashboardBook *b,unsigned int fp,unsigned int from,unsigned int tp,unsigned int to)
{struct AHDashboardTile temp;if(fp>=b->count||tp>=b->count||from>=ah_dashboard_count(&b->pages[fp])||to>=ah_dashboard_count(&b->pages[tp])||(fp==tp&&from==to))return 0;temp=b->pages[fp].tiles[from];b->pages[fp].tiles[from]=b->pages[tp].tiles[to];b->pages[tp].tiles[to]=temp;return 1;}
